// Rent vs Own regression tests. Run with `npm test`.
//
// These sit alongside the six parity fixtures in scripts/rentVsOwnParity.mjs,
// which are unchanged. Where the expected values here come from (none are
// produced by the JavaScript simulation):
//   - tests/reference/rent_vs_own_edge_cases.json, generated by
//     tests/reference/rent_vs_own_edge_cases.py. It holds (a) the existing
//     Python reference model run at edge-case inputs and (b) closed-form
//     results for scenarios simple enough to solve with a formula.
//   - Hand arithmetic, shown inline.
//   - Mortgage insurance timing from tests/reference/expected_values.py.
//
// On the invariants: each one below is a property of THIS model, stated with
// the reason it holds. None is a claim about renting versus owning in general.
// In particular the tests never assert who "should" win a scenario.
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import {
  simulateRentVsOwn,
  clampInput,
  rentInYear,
  roundDefaultRate,
  DEFAULTS,
  LIMITS,
} from "../src/components/rentVsOwnSim.js";
import { programTerms, miChargedThisMonth, LOAN_PROGRAMS } from "../src/data/loanPrograms.js";
import { computeMonthlyPayment, priceScaledEscrow } from "../src/components/calculator/paymentModel.js";

const ref = JSON.parse(readFileSync(fileURLToPath(new URL("./reference/rent_vs_own_edge_cases.json", import.meta.url)), "utf-8"));

const near = (actual, expected, tol, label = "") =>
  assert.ok(Math.abs(actual - expected) <= tol, `${label} expected ${expected} within ${tol}, got ${actual}`);

describe("reference file is still describing the live defaults", () => {
  // The reference cases start from the tool's defaults. If a default changes,
  // this fails first: regenerate the JSON, then review what moved.
  for (const [key, value] of Object.entries(ref.defaults)) {
    test(`default ${key} is ${value}`, () => assert.equal(DEFAULTS[key], value));
  }
});

describe("edge cases against the independent Python reference", () => {
  for (const [name, expected] of Object.entries(ref.reference)) {
    test(`${name} ${JSON.stringify(expected.inputs)}`, () => {
      const sim = simulateRentVsOwn(expected.inputs);
      near(sim.payment, expected.payment, 0.01, "payment");
      for (const y of ref.years) {
        const got = sim.years[y];
        const want = expected.rows[y];
        near(got.ownerWealth, want.owner, 1, `year ${y} owner wealth`);
        near(got.renterWealth, want.renter, 1, `year ${y} renter wealth`);
        near(got.balance, want.balance, 1, `year ${y} balance`);
        near(got.ownerFund, want.side, 1, `year ${y} owner side fund`);
      }
      assert.equal(sim.breakevenYear, expected.breakeven, "breakeven year");
    });
  }
});

describe("closed-form scenarios", () => {
  const cf = ref.closed_form;

  test("starting positions: renter holds down payment plus closing costs; owner holds equity net of selling costs", () => {
    // 350,000 * 3.5% + 350,000 * 3% = 22,750
    // 350,000 * (1 - 7%) - 337,750 = -12,250
    const y0 = simulateRentVsOwn().years[0];
    assert.equal(y0.renterWealth, 22750);
    near(y0.ownerWealth, -12250, 1e-6);
    assert.equal(cf.start_cash, 22750);
  });

  test("when owning is cheaper every month, the renter's portfolio is only the starting cash compounding", () => {
    const sim = simulateRentVsOwn({ rent0: 20000 });
    assert.equal(sim.flipMonth, 1, "owning is already cheaper in month 1");
    for (const y of ref.years) near(sim.years[y].renterWealth, cf.renter_untouched[y], 0.01, `year ${y}`);
  });

  test("when renting is cheaper every month, the owner has no side fund and wealth is equity net of selling costs", () => {
    const sim = simulateRentVsOwn({ rent0: 100 });
    assert.equal(sim.flipMonth, null, "owning never becomes cheaper");
    for (const y of ref.years) {
      assert.equal(sim.years[y].ownerFund, 0, `year ${y} side fund`);
      near(sim.years[y].ownerWealth, cf.owner_no_side_fund[y], 0.01, `year ${y}`);
    }
  });

  test("zero appreciation: the home is worth its purchase price in every year", () => {
    const sim = simulateRentVsOwn({ homeG: 0 });
    for (const row of sim.years) assert.equal(row.homeVal, 350000);
    // At year 30 the loan is gone, so owner wealth is the sale proceeds plus the side fund.
    const end = sim.years[30];
    near(end.ownerWealth, 350000 * 0.93 + end.ownerFund, 1e-6);
  });
});

describe("structural properties of this model, across every input bound and loan program", () => {
  // One run per (program, numeric input, low or high bound), everything else at
  // its default. These are the valid extremes the page's controls allow.
  const runs = [];
  for (const program of LOAN_PROGRAMS) {
    runs.push({ label: `${program} defaults`, input: { program } });
    for (const [key, [lo, hi]] of Object.entries(LIMITS)) {
      if (key === "hz") continue; // the horizon only selects which year the page reads
      runs.push({ label: `${program} ${key}=${lo}`, input: { program, [key]: lo } });
      runs.push({ label: `${program} ${key}=${hi}`, input: { program, [key]: hi } });
    }
  }

  test(`every output is a finite number (${runs.length} runs)`, () => {
    for (const { label, input } of runs) {
      const sim = simulateRentVsOwn(input);
      assert.equal(sim.years.length, 31, label);
      for (const row of sim.years) {
        for (const k of ["ownerWealth", "renterWealth", "homeVal", "balance", "ownerFund", "advantage"]) {
          assert.ok(Number.isFinite(row[k]), `${label}: year ${row.year} ${k} is ${row[k]}`);
        }
      }
      assert.ok(Number.isFinite(sim.payment) && Number.isFinite(sim.owningMonthOne), label);
    }
  });

  test("the loan balance never rises and is zero at year 30 (fixed payment, 30-year term)", () => {
    for (const { label, input } of runs) {
      const { years } = simulateRentVsOwn(input);
      for (let y = 1; y <= 30; y++) assert.ok(years[y].balance <= years[y - 1].balance + 1e-6, `${label}: year ${y}`);
      near(years[30].balance, 0, 1e-6, label);
    }
  });

  // Holds in this model because a side fund only ever receives a non-negative
  // deposit (the monthly saving of whichever side pays less) and the allowed
  // investment returns are positive. A model with withdrawals or negative
  // returns would not have this property.
  test("neither side fund goes negative, given non-negative deposits and positive returns", () => {
    for (const { label, input } of runs) {
      for (const row of simulateRentVsOwn(input).years) {
        assert.ok(row.ownerFund >= 0, `${label}: owner fund year ${row.year}`);
        assert.ok(row.renterWealth >= 0, `${label}: renter portfolio year ${row.year}`);
      }
    }
  });

  test("advantage is owner wealth minus renter wealth; breakeven is the first year it is not negative", () => {
    for (const { label, input } of runs) {
      const sim = simulateRentVsOwn(input);
      for (const row of sim.years) near(row.advantage, row.ownerWealth - row.renterWealth, 1e-6, label);
      const first = sim.years.findIndex((row) => row.advantage >= 0);
      assert.equal(sim.breakevenYear, first === -1 ? null : first, label);
      const flipsBack = first !== -1 && sim.years.slice(first).some((row) => row.advantage < 0);
      assert.equal(sim.leadChangesLater, flipsBack, label);
    }
  });
});

describe("direction checks that follow from the model's definitions", () => {
  test("raising the selling cost lowers owner wealth by exactly that share of the home's value, and leaves the renter alone", () => {
    const a = simulateRentVsOwn({ sellPct: 6 });
    const b = simulateRentVsOwn({ sellPct: 8 });
    for (let y = 0; y <= 30; y++) {
      near(a.years[y].ownerWealth - b.years[y].ownerWealth, a.years[y].homeVal * 0.02, 1e-6, `year ${y}`);
      assert.equal(a.years[y].renterWealth, b.years[y].renterWealth);
    }
  });

  test("a higher starting rent never helps the renter and never hurts the owner", () => {
    const rents = [800, 1500, 2000, 3000, 6000].map((rent0) => simulateRentVsOwn({ rent0 }));
    for (let i = 1; i < rents.length; i++) {
      for (let y = 0; y <= 30; y++) {
        assert.ok(rents[i].years[y].renterWealth <= rents[i - 1].years[y].renterWealth + 1e-6, `renter year ${y}`);
        assert.ok(rents[i].years[y].ownerWealth >= rents[i - 1].years[y].ownerWealth - 1e-6, `owner year ${y}`);
      }
    }
  });

  // Stated with maintenance off on purpose. With maintenance on, a faster
  // appreciating home also costs more to maintain, so "more appreciation is
  // always better for the owner" is not guaranteed and is not asserted.
  test("with maintenance off, more appreciation raises owner wealth after year 0 and does not touch the renter", () => {
    const low = simulateRentVsOwn({ homeG: 2, maintRate: 0 });
    const high = simulateRentVsOwn({ homeG: 6, maintRate: 0 });
    for (let y = 1; y <= 30; y++) {
      assert.ok(high.years[y].ownerWealth > low.years[y].ownerWealth, `owner year ${y}`);
      assert.equal(high.years[y].renterWealth, low.years[y].renterWealth);
    }
  });

  test("higher closing costs give the renter more starting cash and do not change the owner's numbers", () => {
    const low = simulateRentVsOwn({ ccPct: 0 });
    const high = simulateRentVsOwn({ ccPct: 6 });
    for (let y = 0; y <= 30; y++) {
      assert.ok(high.years[y].renterWealth > low.years[y].renterWealth, `renter year ${y}`);
      assert.equal(high.years[y].ownerWealth, low.years[y].ownerWealth);
    }
  });
});

describe("mortgage insurance timing", () => {
  // Assumptions pinned, stated precisely:
  //   Conventional: PMI is charged in a month when the START-of-month balance is
  //     above 78% of the ORIGINAL price, on scheduled payments only (this tool
  //     has no extra payments, so scheduled and actual balances are the same).
  //     miDropMonth is the first month it is NOT charged. The reference gives
  //     the first month whose END balance is at or below 78%; the month after
  //     that is the first uncharged month.
  //   FHA: for the life of the loan under 10% down; 132 months at 10% or more.
  //   USDA: for the life of the loan. VA: none.
  // The premium amount is flat for as long as it is charged. See the report for
  // how that compares with how FHA and USDA actually bill.
  test("Conventional 5% down at 6.75%: last PMI month 139, first month without it 140", () => {
    const sim = simulateRentVsOwn({ program: "Conventional", downPct: 5 });
    assert.equal(sim.chargesMI, true);
    assert.equal(sim.miDropMonth, 140);
  });

  test("Conventional 3.5% down at 6.75%: first month without PMI is 146", () => {
    assert.equal(simulateRentVsOwn({ program: "Conventional", downPct: 3.5 }).miDropMonth, 146);
  });

  test("Conventional 20% down: no PMI at all", () => {
    const sim = simulateRentVsOwn({ program: "Conventional", downPct: 20 });
    assert.equal(sim.chargesMI, false);
    assert.equal(sim.miDropMonth, null);
  });

  test("FHA under 10% down: premium for the life of the loan", () => {
    for (const downPct of [3.5, 9.99]) {
      const sim = simulateRentVsOwn({ program: "FHA", downPct });
      assert.equal(sim.chargesMI, true);
      assert.equal(sim.miDropMonth, null, `${downPct}% down`);
    }
  });

  test("FHA 10% or more down: premium for 132 months, gone in month 133", () => {
    assert.equal(simulateRentVsOwn({ program: "FHA", downPct: 10 }).miDropMonth, 133);
  });

  test("USDA: annual fee for the life of the loan. VA: no monthly insurance", () => {
    const usda = simulateRentVsOwn({ program: "USDA", downPct: 0 });
    assert.equal(usda.chargesMI, true);
    assert.equal(usda.miDropMonth, null);
    assert.equal(simulateRentVsOwn({ program: "VA", downPct: 0 }).chargesMI, false);
  });

  test("the per-month rule at its exact boundaries", () => {
    const price = 350000;
    assert.equal(miChargedThisMonth({ miMode: "ltv78", balance: price * 0.78, price, month: 50 }), false); // exactly 78%
    assert.equal(miChargedThisMonth({ miMode: "ltv78", balance: price * 0.78 + 0.01, price, month: 50 }), true);
    assert.equal(miChargedThisMonth({ miMode: "11yr", balance: 200000, price, month: 132 }), true);
    assert.equal(miChargedThisMonth({ miMode: "11yr", balance: 200000, price, month: 133 }), false);
    assert.equal(miChargedThisMonth({ miMode: "life", balance: 1, price, month: 360 }), true);
    assert.equal(miChargedThisMonth({ miMode: "life", balance: 0, price, month: 360 }), false); // paid off
    assert.equal(miChargedThisMonth({ miMode: "none", balance: 300000, price, month: 1 }), false);
  });

  test("an ineligible down payment is flagged with a reason, not silently simulated as eligible", () => {
    const conv = programTerms({ program: "Conventional", price: 350000, downPct: 2.99 });
    assert.equal(conv.eligible, false);
    assert.match(conv.ineligibleReason, /3%/);
    const fha = programTerms({ program: "FHA", price: 350000, downPct: 3.49 });
    assert.equal(fha.eligible, false);
    assert.match(fha.ineligibleReason, /3\.5%/);
    assert.equal(programTerms({ program: "FHA", price: 350000, downPct: 3.5 }).ineligibleReason, null);
  });
});

describe("agreement with the mortgage calculator", () => {
  const cases = [
    { program: "Conventional", downPct: 3.5 },
    { program: "Conventional", downPct: 20 },
    { program: "FHA", downPct: 3.5 },
    { program: "FHA", downPct: 10 },
    { program: "VA", downPct: 0, vaUsage: "first" },
    { program: "VA", downPct: 0, vaUsage: "subsequent" },
    { program: "VA", downPct: 5, vaUsage: "exempt" },
    { program: "USDA", downPct: 0 },
  ];
  for (const c of cases) {
    test(`${c.program} ${c.downPct}% down${c.vaUsage ? ` (${c.vaUsage})` : ""}: same P&I and same month-one payment`, () => {
      const sim = simulateRentVsOwn(c);
      const { taxes, insurance } = priceScaledEscrow(DEFAULTS.price, DEFAULTS.taxPct, DEFAULTS.insPct / 100);
      const calc = computeMonthlyPayment({ ...c, price: DEFAULTS.price, term: 30, rate: DEFAULTS.rate, taxes, insurance });
      near(sim.payment, calc.pi, 1e-9, "P&I");
      near(sim.owningMonthOne, calc.total, 1e-9, "month-one total");
    });
  }
});

describe("input handling", () => {
  test("in-range values pass through unchanged, including the valid extremes", () => {
    for (const [key, [lo, hi]] of Object.entries(LIMITS)) {
      assert.equal(clampInput(key, lo), lo, `${key} low bound`);
      assert.equal(clampInput(key, hi), hi, `${key} high bound`);
    }
    assert.equal(clampInput("homeG", 0), 0); // zero appreciation is a valid input
    assert.equal(clampInput("rate", 6.75), 6.75);
  });

  test("out-of-range values are pulled to the nearest bound", () => {
    for (const [key, [lo, hi]] of Object.entries(LIMITS)) {
      assert.equal(clampInput(key, lo - 1), lo, `${key} below`);
      assert.equal(clampInput(key, hi + 1), hi, `${key} above`);
    }
    assert.equal(clampInput("homeG", -3), 0); // negative appreciation is outside this tool's range
    assert.equal(clampInput("rate", 0), 3);
    assert.equal(clampInput("rate", 18), 10);
  });

  test("values that are not finite numbers fall back to the default", () => {
    for (const key of Object.keys(LIMITS)) {
      for (const bad of [NaN, Infinity, -Infinity, undefined, null, "abc"]) {
        assert.equal(clampInput(key, bad), DEFAULTS[key], `${key} given ${bad}`);
      }
    }
  });

  test("non-numeric fields are not clamped", () => {
    assert.equal(clampInput("program", "FHA"), "FHA");
    assert.equal(clampInput("vaUsage", "exempt"), "exempt");
  });

  // The page routes every typed value, slider move, and live rate through
  // clampInput or an explicit range check before it reaches the simulation.
  // The simulation itself does not re-check.
  test.todo("simulateRentVsOwn: reject or clamp non-finite inputs itself instead of relying on the page");
});

describe("small helpers", () => {
  test("rent steps up once a year", () => {
    assert.equal(rentInYear(2000, 4.1, 1), 2000);
    near(rentInYear(2000, 4.1, 2), 2082, 1e-9);
    near(rentInYear(2000, 4.1, 11), 2000 * 1.041 ** 10, 1e-9);
    assert.equal(rentInYear(2000, 0, 30), 2000);
  });

  test("the default rate rounds to the nearest eighth and adds an eighth", () => {
    assert.equal(roundDefaultRate(6.43), 6.5); //  nearest eighth 6.375, plus 0.125
    assert.equal(roundDefaultRate(6.5), 6.625);
    assert.equal(roundDefaultRate(6.94), 7.125); // nearest eighth 7.0, plus 0.125
  });
});
